use crate::stage13::SecureBootOtp;use crate::stage14::SecureBootPolicy;use crate::stage15::{SecurityPolicyError,SecurityPolicyReport};
#[derive(Clone,Copy,Debug,PartialEq,Eq)]pub struct SecureInitState{pub programmed_now:bool,pub security_level:u8}
#[derive(Clone,Copy,Debug,PartialEq,Eq)]pub enum SecureInitError<E>{Policy(SecurityPolicyError<E>),VerificationFailed{first:u8,second:u8}}
pub fn establish_secure_init<I:SecureBootOtp>(io:&mut I,security_bytes:[u8;2],mode:u8)->Result<SecureInitState,SecureInitError<I::Error>>{let SecurityPolicyReport{secure_boot,security_level}=crate::stage15::evaluate_security_policy(io,security_bytes,mode).map_err(SecureInitError::Policy)?;match secure_boot{SecureBootPolicy::Enabled=>Ok(SecureInitState{programmed_now:false,security_level}),SecureBootPolicy::EnabledNow=>Ok(SecureInitState{programmed_now:true,security_level}),SecureBootPolicy::VerificationFailed{first,second}=>Err(SecureInitError::VerificationFailed{first,second})}}
#[cfg(test)]mod tests{use super::*;struct O{v:u8}impl SecureBootOtp for O{type Error=();fn read_secure_byte(&mut self,_:u16)->Result<u8,()>{Ok(self.v)}fn write_secure_byte(&mut self,_:u16,v:u8)->Result<(),()>{self.v=v;Ok(())}}#[test]fn init(){let mut o=O{v:0};assert_eq!(establish_secure_init(&mut o,[0x30,0],1),Ok(SecureInitState{programmed_now:true,security_level:2}));let mut bad=O{v:3};assert!(matches!(establish_secure_init(&mut bad,[0x30,0],1),Err(SecureInitError::VerificationFailed{..})));}}
